olor: #36000d !important;\n}\n\ni.mdi-av-play-arrow {\n    background: #f2d337;\n    margin-left: 0px;\n}\n\nnav .nav-wrapper i {\n    display: block;\n    font-size: 2.85rem;\n    color: #cd0324;\n    position: relative;\n    right: 1px;\n}\n\n.qw-playerbutton i {\n    height: 46px !important;\n    line-height: 46px !important;\n    margin: 0 auto 0 1px;\n}\n\n.maincolor a {\n    color: #fff !important;\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 2px;\n}\n\n.qw-footer-widgets.maincolor a {\n    color: #333 !important;\n    font-size: 14px;\n    text-transform: uppercase;\n    letter-spacing: 2px;\n}\n\nnav a.button-collapse {\n    position: absolute !important;\n    top: 0;\n    left: 15px;\n}\n\n.cbp-header-title {\n    display: none;\n}\n\nh4,h5 {\n    display: none;\n}\n\n.cbp-vm-options {\n    display: none;\n}\n\n.select-wrapper input.select-dropdown {\n    font-size: 1.5rem;\n    text-align: center;\n}\n\n.select-wrapper .mdi-navigation-arrow-drop-down {\n    top: -27px;\n    font-size: 62px;\n    right: 10px;\n}\n\n .dropdown-content li>span {\n    font-size: 1.6rem;\n    color: #555555;\n    display: block;\n    padding: 1rem 1rem;\n    text-align:center;\n    border-bottom: 1px solid #ddd\n}\n\n.page-id-2433 .qw-content.qw-relative.z-depth-1  {\n    width: 100%;\n    padding: 0px!important;\n}\n\n#qwSingleContainer{\n    padding: 20px ;\n    background:#fff;\n}\n\n.maincolor-text {\n    color: #333!important;\n    padding-top: 10px;\n    padding-bottom: 10px;\n}\n\n.single-shows .qw-subtitle, .single-shows .qw-subtitle2 {\n    margin: 0;\n    display: block;\n}\n\n\ntable.responsive-table {\n    display: none;\n}\n\n.qw-categories{\n    display: none;\n}\n\n.qw-scrollbutton-footer {\n    display: none;\n}\n\n.qw-scrollbutton-top {\n    display: none;\n}\n\n.onairwidget a.btn {\n    display: none;\n}\n\n.maincolor a hover  {\n    color: #f2d337 !important;\n}', 'on-air', '', 'inherit', 'closed', 'closed', '', '3157-revision-v1